import json,csv,statistics,math
csv_path='${csv_path}'
with open(csv_path,'r') as f:
 reader=csv.DictReader(f);rows=list(reader);fn=reader.fieldnames or []
ec=['date','product','quantity','unit_price','total','region']
nc=['quantity','unit_price','total']
I={'schema_drift':{'detected':False,'unexpected_columns':[],'missing_columns':[]},'type_errors':{'detected':False,'details':[]},'missing_values':{'detected':False,'columns':{}},'duplicates':{'detected':False,'count':0},'outliers':{'detected':False,'details':[]}}
es,as_=set(ec),set(fn)
if as_!=es:
 I['schema_drift']['detected']=True;I['schema_drift']['unexpected_columns']=sorted(list(as_-es));I['schema_drift']['missing_columns']=sorted(list(es-as_))
for c in fn:
 mc=sum(1 for r in rows if not r.get(c) or r.get(c).strip()=='')
 if mc>0:I['missing_values']['detected']=True;I['missing_values']['columns'][c]=mc
s=set()
for r in rows:
 t=tuple(sorted(r.items()))
 if t in s:I['duplicates']['detected']=True;I['duplicates']['count']+=1
 s.add(t)
for c in nc:
 if c in fn:
  vs=[]
  for i,r in enumerate(rows):
   v=r.get(c,'').strip()
   if v:
    try:vs.append((i,float(v)))
    except ValueError:I['type_errors']['detected']=True;I['type_errors']['details'].append({'row':i,'column':c,'value':v})
  if len(vs)>1:
   ns=[x[1] for x in vs];mean=sum(ns)/len(ns);std=math.sqrt(sum((n-mean)**2 for n in ns)/len(ns))
   if std>0:
    for i,fv in vs:
     if abs(fv-mean)>3*std:I['outliers']['detected']=True;I['outliers']['details'].append({'row':i,'column':c,'value':fv})
Rp=[];RR=[dict(r) for r in rows]
for te in I['type_errors']['details']:
 i,c,v=te['row'],te['column'],te['value']
 try:RR[i][c]=str(float(v));Rp.append({'action':'type_fixed','row':i,'column':c})
 except ValueError:RR[i][c]=None;Rp.append({'action':'type_null','row':i,'column':c})
for c in fn:
 if c in nc:
  vs=[float(r[c]) for r in RR if r.get(c) and r[c].strip() and r[c] is not None]
  med=statistics.median(vs) if vs else 0
  for i,r in enumerate(RR):
   if not r.get(c) or r[c].strip()=='' or r[c] is None:RR[i][c]=str(med);Rp.append({'action':'fill_median','row':i,'column':c,'value':med})
 else:
  for i,r in enumerate(RR):
   if not r.get(c) or r[c].strip()=='' or r[c] is None:RR[i][c]='UNKNOWN';Rp.append({'action':'fill_unknown','row':i,'column':c})
if I['duplicates']['detected']:
 u=[];s2=set()
 for r in RR:
  t=tuple(sorted(r.items()))
  if t not in s2:u.append(r);s2.add(t)
 Rp.append({'action':'remove_duplicates','removed':len(RR)-len(u)});RR=u
Rv={'remaining_issues':[],'passed':True}
for c in fn:
 mc=sum(1 for r in RR if not r.get(c) or r[c].strip()=='' or r[c] is None)
 if mc>0:Rv['remaining_issues'].append({'type':'missing_values','column':c,'count':mc});Rv['passed']=False
for c in nc:
 if c in fn:
  for i,r in enumerate(RR):
   v=r.get(c)
   if v and str(v).strip():
    try:float(v)
    except(ValueError,TypeError):Rv['remaining_issues'].append({'type':'type_error','row':i,'column':c});Rv['passed']=False
S={'file':csv_path,'total_rows':len(RR),'columns':fn}
for c in nc:
 if c in fn:
  vs=[]
  for r in RR:
   try:vs.append(float(r[c]))
   except(ValueError,TypeError):pass
  if vs:S[c]={'sum':round(sum(vs),2),'mean':round(sum(vs)/len(vs),2),'min':round(min(vs),2),'max':round(max(vs),2),'count':len(vs)}
print(json.dumps({'file':csv_path,'issues':I,'repairs':Rp,'revalidation':Rv,'statistics':S}))

import json
AR=${all_results}
if isinstance(AR,str):AR=json.loads(AR)
P=[json.loads(r) if isinstance(r,str) else r for r in AR]
M={'quarters':[],'total_rows':0,'total_issues':0,'total_repairs':0,'all_issues':[],'all_repairs':[],'all_revalidations':[]}
for r in P:
 M['quarters'].append(r['statistics']);M['total_rows']+=r['statistics']['total_rows']
 ic=sum(1 for v in r['issues'].values() if isinstance(v,dict) and v.get('detected'));M['total_issues']+=ic
 M['total_repairs']+=len(r['repairs']);M['all_issues'].append({'file':r['file'],'issues':r['issues']});M['all_repairs'].append({'file':r['file'],'repairs':r['repairs']});M['all_revalidations'].append({'file':r['file'],'revalidation':r['revalidation']})
print(json.dumps(M))

import json
M=${merged_data}
if isinstance(M,str):M=json.loads(M)
R={'overall_quality':'GOOD','concerns':[],'recommendations':[]}
if M['total_issues']>10:R['overall_quality']='FAIR';R['concerns'].append('High number of data quality issues detected')
if M['total_repairs']>0:R['recommendations'].append('Review automated repairs for accuracy')
for rv in M['all_revalidations']:
 if not rv['revalidation']['passed']:R['concerns'].append(rv['file']+': revalidation failed');R['overall_quality']='NEEDS_ATTENTION'
print(json.dumps(R))

